1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
37	
38	export interface ScenarioResult {
39	  results: StepResult[];
40	}
41	
42	const PROCESSING_FEE = 5;
43	
44	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	};
50	
51	const FIRST_INSURANCE_PERCENT = 10;
52	
53	// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
54	// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
55	// is 110.00000000000001 in binary floating point. Since the final amount feeds
56	// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
57	const addPercent = (amount: number, percent: number): number =>
58	  amount + (amount * percent) / 100;
59	
60	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
61	
62	const quotePremium = (step: QuoteStep): number => {
63	  const policyBasePremium = step.items.reduce(
64	    (sum, item) => sum + basePremiumOf(item),
65	    0,
66	  );
67	  return Math.ceil(
68	    addPercent(policyBasePremium, FIRST_INSURANCE_PERCENT) + PROCESSING_FEE,
69	  );
70	};
71	
72	const runStep = (step: Step): StepResult => {
73	  if (step.op === "quote") return { premium: quotePremium(step) };
74	  throw new Error(`Unsupported step: ${step.op}`);
75	};
76	
77	export const runScenario = (scenario: Scenario): ScenarioResult => ({
78	  results: scenario.steps.map(runStep),
79	});
